from pycompss.api.task import task
from pycompss.api.api import compss_wait_on

@task(returns=int)
def calculate_degree(row):
    return sum(row)

def main(A):
    degree_futures = []

    for row in A:
        future_degree = calculate_degree(row)
        degree_futures.append(future_degree)

    all_degrees = compss_wait_on(degree_futures)

    if not all_degrees:
        return 0

    return max(all_degrees)
